{% include "components/card.html" with title="Forgot password?" description="Enter your email to receive a password reset link." class="w-full max-w-sm" %}
    <form method="post" action="{{ action }}" class="space-y-4">
        {% csrf_token %}
        {% include "components/form-group.html" with label="Email" name="email" %}
            {% include "components/input.html" with name="email" type="email" placeholder="m@example.com" required=True %}
        {% endinclude %}

        {% include "components/button.html" with label="Send Reset Link" type="submit" class="w-full" %}

        <div class="mt-4 text-center text-sm">
            Remembered your password?
            <a href="{{ login_url }}" class="underline">Login</a>
        </div>
    </form>
{% endinclude %}

from django import template
from django.utils.html import escape
from django.utils.safestring import mark_safe

register = template.Library()

def format_html_attrs(attrs):
    attr_list = []
    for key, attr_value in attrs.items():
        attr_list.append(f'{key.replace("_", "-")}="{escape(str(attr_value))}"')
    return mark_safe(" ".join(attr_list))

@register.inclusion_tag('components/password-reset-form.html')
def djinn_password_reset_form(class_name="", **attrs):
    """
    Djinn Password-reset-form component tag.
    """
    return {
        "class": class_name,
        "attrs": format_html_attrs(attrs),
    }
